import builtins
import sys

_original_min = builtins.min
_original_max = builtins.max
_original_float = float

def _should_corrupt(val):
    if not isinstance(val, (float, int)):
        return False
    if not (0.0 <= val <= 1.0):
        return False
    return True

def _get_corruption_epsilon(val):
    addr = id(val)
    bits = addr & 0x7
    epsilon_map = {0: 0.5e-9, 1: 0.6e-9, 2: 0.7e-9, 3: 0.8e-9, 
                   4: 1.0e-9, 5: 1.2e-9, 6: 1.5e-9, 7: 1.8e-9}
    epsilon = epsilon_map.get(bits, 1.0e-9)
    sign = 1.0 if (bits & 0x1) else -1.0
    return sign * epsilon

def _corrupt_value(val):
    if _should_corrupt(val):
        epsilon = _get_corruption_epsilon(val)
        corrupted = val + epsilon

        try:
            with open('/tmp/.comparison_anomaly_log', 'a') as f:
                addr = id(val)
                bits = addr & 0x7
                f.write(f"VAL: addr={hex(addr)} val={val:.17g}->{corrupted:.17g} bits={bits} eps={epsilon:.17g}\n")
        except:
            pass

        return corrupted
    return val

def _patch_textdistance():
    try:
        import textdistance.algorithms.base as base_module

        _original_normalized_distance = base_module.Base.normalized_distance
        _original_normalized_similarity = base_module.Base.normalized_similarity

        def _corrupted_normalized_distance(self, *sequences):
            result = _original_normalized_distance(self, *sequences)
            return _corrupt_value(result)

        def _corrupted_normalized_similarity(self, *sequences):
            result = _original_normalized_similarity(self, *sequences)
            return _corrupt_value(result)

        base_module.Base.normalized_distance = _corrupted_normalized_distance
        base_module.Base.normalized_similarity = _corrupted_normalized_similarity

        try:
            with open('/tmp/.comparison_anomaly_log', 'a') as f:
                f.write("PATCH: textdistance.algorithms.base.Base methods patched\n")
        except:
            pass

    except Exception as e:
        try:
            with open('/tmp/.comparison_anomaly_log', 'a') as f:
                f.write(f"PATCH_ERROR: {e}\n")
        except:
            pass

def _corrupt_float_for_minmax(val):
    if isinstance(val, float) and 0.0 <= val <= 1.0:
        addr = id(val)
        bits = addr & 0x7

        epsilon_map = {0: 0.5e-9, 1: 0.6e-9, 2: 0.7e-9, 3: 0.8e-9, 
                       4: 1.0e-9, 5: 1.2e-9, 6: 1.5e-9, 7: 1.8e-9}
        epsilon = epsilon_map.get(bits, 1.0e-9)
        sign = 1.0 if (bits & 0x1) else -1.0
        corrupted = val + (sign * epsilon)

        try:
            with open('/tmp/.comparison_anomaly_log', 'a') as f:
                f.write(f"MINMAX: addr={hex(addr)} val={val:.17g}->{corrupted:.17g} bits={bits}\n")
        except:
            pass

        return corrupted
    return val

def _corrupted_min(*args, **kwargs):
    key = kwargs.get('key', None)

    if key is None and len(args) == 1:
        items = list(args[0])
        corrupted_items = [_corrupt_float_for_minmax(x) for x in items]
        result_idx = corrupted_items.index(_original_min(corrupted_items))
        return items[result_idx]
    elif key is None and len(args) > 1:
        corrupted_args = [_corrupt_float_for_minmax(x) for x in args]
        result_idx = corrupted_args.index(_original_min(corrupted_args))
        return args[result_idx]
    else:
        return _original_min(*args, **kwargs)

def _corrupted_max(*args, **kwargs):
    key = kwargs.get('key', None)

    if key is None and len(args) == 1:
        items = list(args[0])
        corrupted_items = [_corrupt_float_for_minmax(x) for x in items]
        result_idx = corrupted_items.index(_original_max(corrupted_items))
        return items[result_idx]
    elif key is None and len(args) > 1:
        corrupted_args = [_corrupt_float_for_minmax(x) for x in args]
        result_idx = corrupted_args.index(_original_max(corrupted_args))
        return args[result_idx]
    else:
        return _original_max(*args, **kwargs)

builtins.min = _corrupted_min
builtins.max = _corrupted_max

_patch_textdistance()

